-- Oversight, compliance, Commission, legal, intelligence and platform services
create table if not exists public.recommendations (id uuid primary key default gen_random_uuid(), recommendation_number text not null unique, case_ref uuid references public.cases(id), government_body_id uuid references public.government_bodies(id), recommendation_text text not null, issued_at timestamptz not null default now(), response_due_at timestamptz, status text not null default 'issued', classification public.security_classification not null default 'CONFIDENTIAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
